  "tags" : [ {
    "name" : "Accrual",
    "description" : "Represents a leave accrual policy that defines how workers earn and accumulate time-off credits (e.g., Annual Leave, Sick Leave) within a company."
  }, {
    "name" : "Accrual_Balance",
    "description" : "Represents a worker's running leave balance for a specific accrual policy, tracking how much leave has been earned, used, carried over, and is currently available for consumption or encashment."
  }, {
    "name" : "Attendance_Summary",
    "description" : "Represents a single time-tracking entry that records how many units a worker worked against a specific earning code within a pay period."
  }, {
    "name" : "Bank_Info",
    "description" : "Represents a worker's bank account details used for payroll disbursement and pay slip generation."
  }, {
    "name" : "Benefit",
    "description" : "Represents a dual-purpose pay component that can function as either an earning or a deduction depending on the `Action` field."
  }, {
    "name" : "Calculation_Method",
    "description" : "Represents a method of computing a pay component amount."
  }, {
    "name" : "Company",
    "description" : "Represents an employing organization in the payroll system."
  }, {
    "name" : "Country",
    "description" : "Represents a geographic country used to scope tax applicability, worker locations, and company locations within the payroll system.\n\n**System vs Custom Records**\n\nCountry records exist in two categories, distinguished by the `Custom` flag:\n- **System records** (`Custom = 0`): Pre-seeded during database initialization."
  }, {
    "name" : "Currency",
    "description" : "Represents a monetary currency used to denominate pay components, payslip line items, and worker/company financial configurations.\n\n**Current Status — Informational Only**\n\nCurrency records are currently used for display and reference purposes only."
  }, {
    "name" : "Deduction",
    "description" : "Represents a worker-specific deduction record defining how a monetary amount is withheld from a worker's pay, along with optional employer contribution, scheduling controls, and goal-tracking fields suited for loan-style deductions.\n\n**Architectural Status — Currently Inactive**\n\nThe `Deduction` entity and all its associated services (`InsertDeduction`, `UpdateDeduction`, `DeleteDeduction`, `ProcessDeductions`, etc.) exist in the codebase but are **not currently active in payroll processing**."
  }, {
    "name" : "Earning",
    "description" : "Represents a compensation component that defines how workers are paid for a specific type of work or entitlement (e.g., regular salary, overtime, bonus, shift differential, or time-off leave credits)."
  }, {
    "name" : "Employment_Info",
    "description" : "Represents a worker's employment contract details, capturing employment dates, termination information, regulatory context, and final-pay eligibility."
  }, {
    "name" : "Pay_Component_Log",
    "description" : "Represents a single line-item entry in the permanent payslip audit trail, recording exactly one pay component (earning, benefit, deduction, tax, or accrual balance) and the amounts applied to a worker for a specific pay slip."
  }, {
    "name" : "Pay_Period",
    "description" : "Represents a defined window of time over which worker compensation is calculated and paid."
  }, {
    "name" : "Payroll_Run",
    "description" : "Represents a single payroll execution event tied to a specific pay period."
  }, {
    "name" : "Pay_Schedule",
    "description" : "Represents a pay schedule that defines the timing, frequency, and calendar rules governing regular payroll processing for workers at a company."
  }, {
    "name" : "Pay_Slip",
    "description" : "Represents the generated payroll record for a single worker within a single payroll run."
  }, {
    "name" : "Position",
    "description" : "Represents a job position within a company, defining the role, compensation structure, and working-time parameters that govern how a worker is paid."
  }, {
    "name" : "Position_Pay_Component",
    "description" : "Records the assignment of a single earnings element or benefit to a job position, establishing the compensation structure that all workers in that position inherit."
  }, {
    "name" : "Role",
    "description" : "Represents a named security persona used for role-based access control within the payroll application."
  }, {
    "name" : "Role_Scope",
    "description" : "Associates a `ROLE` with a `SCOPE` and a permission level (`READ` or `WRITE`), forming the role-based access control matrix for the payroll API."
  }, {
    "name" : "Scope",
    "description" : "Represents a named API endpoint that can be protected through role-based access control."
  }, {
    "name" : "State",
    "description" : "Represents a state, province, or equivalent sub-national geographic subdivision within a country."
  }, {
    "name" : "Statutory_Compliance",
    "description" : "The `Statutory_Compliance` entity represents a worker's government-issued statutory compliance record — a named identifier (e.g., SSS, PhilHealth, Pag-IBIG, TIN) paired with the worker's actual registration number (`Number`) for that compliance type and a validity period (`EffectiveFromDate`/`EffectiveToDate`)."
  }, {
    "name" : "Tax",
    "description" : "The `Tax` entity represents a payroll tax configuration — a named, coded tax rule with employee and/or employer obligations, an optional progressive rate schedule (`Tax_Schedule`), and a currency scope."
  }, {
    "name" : "Tax_Applicability",
    "description" : "The `Tax_Applicability` entity assigns a tax configuration to a geographic jurisdiction."
  }, {
    "name" : "Tax_Schedule",
    "description" : "The `Tax_Schedule` entity represents a single bracket in a progressive tax rate structure."
  }, {
    "name" : "User",
    "description" : "The `User` entity represents an application-level identity in the payroll system — a login credential and access profile."
  }, {
    "name" : "User_Role",
    "description" : "The `User_Role` entity is a junction table that assigns a role to a user, forming the authorization bridge between identity (`USER`) and capability (`ROLE`)."
  }, {
    "name" : "Worker",
    "description" : "The `Worker` entity represents an employment profile in the payroll system."
  }, {
    "name" : "Worker_Pay_Component",
    "description" : "The `Worker_Pay_Component` entity represents the assignment of a pay component — either an earning or a benefit — to a specific worker."
  }, {
    "name" : "Worker_Position",
    "description" : "The `Worker_Position` entity represents the assignment of a worker to a position within the organization."
  } ],
